import {
  Button as AriaButton,
  Disclosure,
  DisclosurePanel,
} from "react-aria-components";
import type { DisclosureProps as AriaDisclosureProps } from "react-aria-components";
import { Button } from "./Button";
import { ChevronDown } from "./icons";
import { Children, type ReactNode, type Ref } from "react";
import "./Collapsible.css";

export interface CollapsibleProps
  extends Omit<AriaDisclosureProps, "className" | "children"> {
  /**
   * Where the chevron sits. `start` (default) leads a trigger that hugs its own name, a control in a
   * column of content. `end` makes the trigger a ROW: it spans the width, the title at the start and
   * the chevron at the far end, the shape of a summary line closing a card.
   *
   * @default "start"
   */
  chevronPlacement?: "start" | "end";
  /**
   * How the trigger draws, from the action-variant vocabulary. `ghost` (default) is the bare
   * disclosure control: a transparent box with a chevron, sized by `chevronPlacement`. `secondary`
   * makes the trigger this system's secondary `Button`, spanning the Collapsible's width with no
   * chevron, for a disclosure opened by a call to action. Either way it is React Aria's trigger, so
   * `aria-expanded` and `aria-controls` are wired the same; `chevronPlacement` applies to `ghost` only.
   * A title that names the state ("Show" / "Hide") reads `isExpanded` from the controlled props.
   *
   * @default "ghost"
   */
  triggerVariant?: "ghost" | "secondary";
  /** Trigger title. */
  title: ReactNode;
  /**
   * Panel content. Text-only content (strings and numbers) is wrapped in a paragraph that carries the
   * panel's type role, so it stands one text inset in from the panel's line, as every text does;
   * anything else renders as given, on that line, and carries its own role (`Text`).
   */
  children?: ReactNode;
  /** Additional class. sd-collapsible is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * One CSS knob is public: `--sd-collapsible-trigger-gap`, the seam between the trigger and the panel
 * content. Set it on your own element to the gap your content uses when that is wider than
 * the trigger's padding; the panel adds the difference. Unset, the seam is the trigger's padding.
 */
export function Collapsible({
  chevronPlacement = "start",
  triggerVariant = "ghost",
  title,
  children,
  className,
  ...props
}: CollapsibleProps) {
  return (
    <Disclosure
      {...props}
      data-trigger-variant={triggerVariant}
      className={className ? `sd-collapsible ${className}` : "sd-collapsible"}
    >
      {({ isExpanded }) => (
        <>
          {triggerVariant === "secondary" ? (
            /* The system's Button, not a restyled one: `slot="trigger"` takes the Disclosure's
               trigger props through React Aria's ButtonContext, exactly as the bare trigger does. */
            <Button slot="trigger" variant="secondary">
              {title}
            </Button>
          ) : (
            <AriaButton
              slot="trigger"
              className="sd-collapsible__trigger"
              data-expanded={isExpanded || undefined}
              data-chevron-placement={chevronPlacement}
            >
              <span
                aria-hidden="true"
                className="sd-collapsible__chevron"
                data-expanded={isExpanded || undefined}
              >
                <ChevronDown size="1em" />
              </span>
              {/* `label`, not `title`: this text names a control, it does not head a section
                  (naming-convention role table #5). The ARIA APG Disclosure pattern needs no
                  heading — that requirement belongs to Accordion, which is why this component
                  renders no <Heading> while AccordionItem does.
                  @usageInvariant accordion-collapsible-heading */}
              <span className="sd-collapsible__title sd-type-label-medium">{title}</span>
            </AriaButton>
          )}
          {/* The variant rides on the panel too, so its seam rule is a same-element selector. */}
          <DisclosurePanel
            className="sd-collapsible__panel sd-type-body-medium"
            data-trigger-variant={triggerVariant}
          >
            {isTextOnly(children) ? (
              <p className="sd-collapsible__panel-text sd-type-body-medium">{children}</p>
            ) : (
              children
            )}
          </DisclosurePanel>
        </>
      )}
    </Disclosure>
  );
}

/** Whether the panel holds only text, which the component then draws as its own paragraph. */
function isTextOnly(content: ReactNode): boolean {
  const parts = Children.toArray(content);
  return parts.length > 0 && parts.every((p) => typeof p === "string" || typeof p === "number");
}

/* Collapsible — a STANDALONE disclosure, deliberately lighter than Accordion.
   The ARIA APG splits these two: an Accordion header button "is wrapped in an element with role
   heading", while the Disclosure pattern requires only `role=button` + `aria-expanded` — no heading
   at all. So this component renders no <Heading> (Accordion does), and its chrome follows: no rules,
   no full-width row, a `label`-role name instead of a `title`. GOV.UK says the same thing from the
   usage side — use a details/disclosure rather than an accordion for one section, because it "is
   less visually prominent". If this ever needs to read as a section, that is an Accordion. */
.sd-collapsible {
  width: 100%;
}

/* A `secondary` trigger is a Button, which dims itself; dimming the root too would compound. */
.sd-collapsible[data-disabled]:not([data-trigger-variant="secondary"]) {
  opacity: var(--sd-state-disabled);
}

/* `triggerVariant="secondary"`: the trigger is a Button, and a grid stretches it across the
   Collapsible's width. The track does it, not a width on the Button, so this file sets no geometry
   on another component's box (ButtonGroup's `fill` layout takes the same route). */
.sd-collapsible[data-trigger-variant="secondary"] {
  display: grid;
}

/* Hug, not full width: the trigger is an affordance sized to its own name, so `inline-flex` lets
   the surrounding block stay full width while the control itself stays small. */
.sd-collapsible__trigger {
  position: relative;
  display: inline-flex;
  /* CENTER, not `flex-start`. What `flex-start` buys is the wrapping title: centring drops the
     chevron into the gap between the two lines, about 9px below the first line's centre. What it
     costs is everything whose first line is TALLER than one line of the title's role, because the
     chevron below is sized to exactly that and top-aligning pins it to the top of a taller row, so
     a tall first child (a Badge) leaves the chevron above the word it points at.
     Neither value is right for both. CSS cannot say "centre on the first LINE BOX" for a sibling,
     `baseline` splits the difference and lands 3px out in both, so the DS picks the case that
     actually occurs. Centre is that case: a Collapsible title is the `label` role, which NAMES a
     control and is therefore short by construction, and no story in the library wraps one. The
     Checkbox/Radio/Switch precedent `flex-start` was taken from does not transfer, because those
     labels are full option SENTENCES that are meant to wrap. A wrapping disclosure title is
     already a smell, and optimising for it was optimising for the rarer case. */
  align-items: center;
  gap: var(--sd-collapsible-trigger-gap);
  min-height: var(--sd-collapsible-trigger-min-height);
  padding-block: var(--sd-collapsible-trigger-padding-block);
  /* Zero inline padding, and it has to be DECLARED rather than merely left out: this is a <button>,
     and Chrome's UA sheet pads one `padding: 1px 6px`, so leaving the declaration out leaves the
     content 6px out of column. A literal zero is what the naming rules allow
     here, and an always-zero token would be noise in the manifest and in Figma.
     The box hugs its content so the chevron and the title sit on the same edge as whatever
     surrounds the control. A rounded hover target comes from the state layer overhanging instead
     (see ::after below), by `space.small` like every fill-only row (component-contract.md §6 rule 8),
     so padding here would only step the control out of its own column. */
  padding-inline: 0;
  /* A RESTING corner, not a focus-only one: the trigger is transparent at rest but paints a tint on
     hover/pressed, and the ::after state layer below takes this radius — without it the tint is a
     square block behind a rounded-corner library. Same idiom as a ghost Button. */
  border-radius: var(--sd-collapsible-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-collapsible-trigger-background);
  color: var(--sd-collapsible-trigger-foreground);
  border: 0;
  font: inherit;
  text-align: start;
  cursor: pointer;
  outline: none;
}

/* Interaction state-layer overlay (ADR-0009), and the half of this control's geometry that the box
   gave up. `inset-block: 0` hugs the trigger, `inset-inline` goes NEGATIVE by the overhang token
   (`text-inset.inline`, the rule-8 bleed every fill-only row shares), so the tint rounds away from
   content that stays flush with the column. `border-radius: inherit` still applies: the radius is on the
   trigger and the layer is bigger than it, which is the point — a corner curve on a box clamped to
   the glyphs would clip into the chevron and the first letter. */
.sd-collapsible__trigger::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-collapsible-trigger-state-layer-overhang));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-collapsible__trigger[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-collapsible__trigger[data-pressed]::after {
  background: var(--sd-state-pressed);
}

/* The ring sits on the trigger, not the block: the trigger is what takes focus, and a ring around
   the whole disclosure would draw a full-width box around a small control.
   It is drawn on the ::after rather than on the button box, so it traces the SAME rounded rectangle
   the hover tint does. On the box it would hug the content instead, 2x the overhang narrower than
   the shape that lights up on hover, and the two indicators would disagree about where the control
   ends. The transparent outline rides along on the same element, so the forced-colors fallback
   (`component-contract.md` §6.3, where `box-shadow` computes to `none`) lands on that shape too. */
.sd-collapsible__trigger[data-focus-visible]::after {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-collapsible__trigger[data-disabled] {
  /* Dimmed once, by the root: RAC disables the trigger with its Disclosure. */
  cursor: not-allowed;
}

/* `chevronPlacement="end"`: the trigger is a row across the width, the chevron after the title at
   the far end. Order, not markup, moves it, so the reading order stays title-led for both. */
.sd-collapsible__trigger[data-chevron-placement="end"] {
  display: flex;
  width: 100%;
  flex-direction: row-reverse;
  justify-content: space-between;
}

.sd-collapsible__chevron {
  flex: 0 0 auto;
  color: var(--sd-collapsible-chevron-foreground);
  /* A flex box exactly one title-line tall: `display: flex` drops the inline-baseline descender
     that made the box 21px for a 16px glyph. The glyph then centres inside its own line box, and
     that box is what the trigger's `align-items: center` centres against the title row. The height
     is a separate job from the alignment: it keeps a bare chevron from being measured by its
     glyph's descender. */
  display: flex;
  align-items: center;
  height: var(--sd-collapsible-chevron-height);
  font-size: var(--sd-collapsible-chevron-font-size);
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-collapsible__chevron[data-expanded] {
  transform: rotate(180deg);
}

.sd-collapsible__title {
  color: var(--sd-collapsible-title-foreground);
}

.sd-collapsible__panel {
  /* No inline padding either, so a box placed in the panel lands on the same line as the trigger
     and the column around them both, and its text one inset in from it. It carried two tokens for
     these edges and they are gone rather than set to zero, the same call the block-start edge
     already made in `collapsible.panel.padding.block.end`'s own description: an always-zero token
     is noise in the manifest, in Figma and in the docs. DECLARED zero, not left out: the panel's role class only
     lends the font, and its generated inset would put every text inside one inset deeper
     (component-contract.md rule 8, the region row, as `.sd-card__content`). */
  padding-inline: 0;
  color: var(--sd-collapsible-panel-foreground);
  outline: none;
}
/* panel-text: the paragraph Collapsible wraps text-only children in, so words passed bare take the
   panel's role and its inset, one inset in from the panel's line. Content the consumer draws carries
   its own role. */
.sd-collapsible__panel-text {
  margin: 0;
}
/* Bottom padding only, matching Accordion: the trigger above already ends with its own padding, so
   a symmetric top here would stack between the name and the content it introduces.
   Same `:not([hidden])` guard as Accordion's panel: React Aria collapses with
   `hidden="until-found"` (`content-visibility: hidden`, not `display: none`), so the box survives
   and an unguarded block padding renders as dead space under the collapsed trigger. */
.sd-collapsible__panel:not([hidden]) {
  /* The seam under the trigger is the trigger's own block padding, which is right when the content
     is spaced at that rung too. A consumer whose content is spaced wider sets
     `--sd-collapsible-trigger-gap` to that gap on its own element (it inherits; no selector reaches in),
     and the panel adds only what the trigger's padding leaves short, so the head binds to its
     content at least as tightly as the content binds to itself (token-contract.md § By
     relationship, attachment). Unset, it adds nothing. */
  padding-block-start: max(0px, calc(var(--sd-collapsible-trigger-gap, 0px) - var(--sd-collapsible-trigger-padding-block)));
  padding-block-end: var(--sd-collapsible-panel-padding-block-end);
}
/* A Button carries no outer padding to seam it from the panel, so the seam is stated whole: the
   ghost trigger's own padding unless the consumer's gap is wider, the same seam either way. */
.sd-collapsible__panel[data-trigger-variant="secondary"]:not([hidden]) {
  padding-block-start: max(var(--sd-collapsible-trigger-padding-block), var(--sd-collapsible-trigger-gap, 0px));
}

/* Fires only when a descendant of the panel takes keyboard focus — consumer content, not the
   trigger (which rings itself above). */
.sd-collapsible__panel[data-focus-visible-within] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
  border-radius: var(--sd-collapsible-panel-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

@media (prefers-reduced-motion: reduce) {
  .sd-collapsible__chevron {
    transition: none;
  }
}
